      <div className="[grid-area:1_/_1] font-['Inter:Medium',_sans-serif] font-medium leading-[0] ml-[101.86px] mt-0 not-italic relative text-[#d0d5dd] text-[12.301px] text-center translate-x-[-50%] w-[137.754px]">
